-- Adds the slot equipment the importer's allow-list missed (importers skill, bug 8): the Dumper (written
-- "Dumper (Front)" / "Dumper (Rear)") on 5 mechs and the Fluid Suction System (Light - Mech) on 2. Like
-- the rest of the allow-list each is one item per mech, so the two-dumper Lumberjack LM4/C and MuckRaker
-- GMMM-2 get one.
--
-- Generated from a database V3_8 to V3_10 loaded and the fixed importer then re-imported (mechs, then
-- vehicles, mm-data at d195e171b3c87801c8dbc5ffcb5f763e5da57483), by comparing each unit's items before
-- and after: only these 7 were added, nothing changed or went. An item is added only if the unit doesn't
-- have it yet, so this also runs on a database that was re-imported since.
-- Data migrations after V3_8 update what's stored; see the importers skill.

-- 1. The items
INSERT INTO equipment (id, crit_slots, damage, heat, long_range, medium_range, min_range, name, short_range, tech, tonnage, display_name) SELECT 'a1861e9a-92df-49f7-aa84-bc2772aa2ad7', 0, NULL, 0, 0, 0, 0, 'dumper', 0, 'INNER_SPHERE', 0, 'Dumper' WHERE NOT EXISTS (SELECT 1 FROM equipment WHERE name = 'dumper' AND tech = 'INNER_SPHERE');
INSERT INTO equipment (id, crit_slots, damage, heat, long_range, medium_range, min_range, name, short_range, tech, tonnage, display_name) SELECT 'a1c7a82f-0c62-40a3-957c-7d1cdecade3b', 0, NULL, 0, 0, 0, 0, 'fluidsuctionsystem(light-mech)', 0, 'INNER_SPHERE', 0, 'Fluid Suction System (Light - Mech)' WHERE NOT EXISTS (SELECT 1 FROM equipment WHERE name = 'fluidsuctionsystem(light-mech)' AND tech = 'INNER_SPHERE');
INSERT INTO slang (id, term, lookup, kind) SELECT '93620373-bddc-4eb9-aed2-68a4339a106c', 'Fluid Suction System (Light - Mech)', 'fluidsuctionsystemlightmech', 'ALIAS' WHERE NOT EXISTS (SELECT 1 FROM slang WHERE kind = 'ALIAS' AND lookup = 'fluidsuctionsystemlightmech' AND term = 'Fluid Suction System (Light - Mech)');
INSERT INTO slang (id, term, lookup, kind) SELECT '978215a2-c042-4ea2-b749-aaec8252eeac', 'Light Fluid Suction System (Mech)', 'lightfluidsuctionsystemmech', 'ALIAS' WHERE NOT EXISTS (SELECT 1 FROM slang WHERE kind = 'ALIAS' AND lookup = 'lightfluidsuctionsystemmech' AND term = 'Light Fluid Suction System (Mech)');
INSERT INTO slang_equipment (slang_id, equipment_id) SELECT s.id, e.id FROM slang s, equipment e WHERE s.kind = 'ALIAS' AND s.lookup = 'fluidsuctionsystemlightmech' AND s.term = 'Fluid Suction System (Light - Mech)' AND e.name = 'fluidsuctionsystem(light-mech)' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM slang_equipment x WHERE x.slang_id = s.id AND x.equipment_id = e.id);
INSERT INTO slang_equipment (slang_id, equipment_id) SELECT s.id, e.id FROM slang s, equipment e WHERE s.kind = 'ALIAS' AND s.lookup = 'lightfluidsuctionsystemmech' AND s.term = 'Light Fluid Suction System (Mech)' AND e.name = 'fluidsuctionsystem(light-mech)' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM slang_equipment x WHERE x.slang_id = s.id AND x.equipment_id = e.id);

-- 2. Each unit's new item, added unless the unit has it already (a database re-imported since)
WITH added AS (INSERT INTO unit_equipment (id, location, omni_pod, rear_facing, tonnage, turret_equipped, equipment_id, fire_control, jump_boost) SELECT gen_random_uuid(), 'LEFT_TORSO', 'f', 'f', 0, 'f', e.id, NULL, NULL FROM equipment e, generate_series(1, 1) WHERE e.name = 'dumper' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM unit_mech_equipment ume JOIN unit_equipment ue ON ue.id = ume.mech_equipment_id WHERE ume.unit_id = '0b00566b-92a8-44a9-a3db-a4b152201e27' AND ue.equipment_id = e.id) RETURNING id) INSERT INTO unit_mech_equipment (unit_id, mech_equipment_id) SELECT '0b00566b-92a8-44a9-a3db-a4b152201e27', id FROM added; -- Grommet D90 MilitiaMech: dumper
WITH added AS (INSERT INTO unit_equipment (id, location, omni_pod, rear_facing, tonnage, turret_equipped, equipment_id, fire_control, jump_boost) SELECT gen_random_uuid(), 'RIGHT_TORSO', 'f', 'f', 0, 'f', e.id, NULL, NULL FROM equipment e, generate_series(1, 1) WHERE e.name = 'dumper' AND e.tech = 'INNER_SPHERE' AND NOT EXISTS (SELECT 1 FROM unit_mech_equipment ume JOIN unit_equipment ue ON ue.id = ume.mech_equipment_id WHERE ume.unit_id = '45e34571-281e-45f1-9593-79670aae0e2c' AND ue.equipment_id = e.id) RETURNING id) INSERT INTO unit_mech_equipment (unit_id, mech_equipment_id) SELECT '45e34571-281e-45f1-9593-79670aae0e2c', id FROM added; -- Lumberjack LM1/A: dumper
